"""Error hierarchy shared by every tallybook module."""


class TallybookError(Exception):
    """Base of every error caused by what the user asked for.

    ``message`` is the human text, ``code`` a short stable word. ``detail`` is an optional
    dict with extra facts (for example ``{"index": 3}``).
    """

    code = "error"

    def __init__(self, message, code=None, detail=None):
        message = str(message)
        super().__init__(message)
        self.message = message
        if code is not None:
            self.code = code
        self.detail = detail

    def __str__(self):
        return self.message


class ParseError(TallybookError):
    code = "parse"


class ValidationError(TallybookError):
    code = "validation"


class NotFoundError(TallybookError):
    code = "not_found"


class ConflictError(TallybookError):
    code = "conflict"
