    """Every command of the program."""
    from tallybook.cli import calc, commands_book, commands_data

    return commands_book.COMMANDS + commands_data.COMMANDS + calc.COMMANDS


def _root_help(commands):
    lines = [
        GLOBAL_USAGE.rstrip("\n"),
        "",
        "options:",
        "  --db FILE      the book file (default: $TALLYBOOK_DB, else tallybook.db)",
        "  --today DATE   what today is (default: the real date)",
        "  --version      print the version and stop",
        "  -h, --help     print this help and stop",
        "",
        "commands:",
    ]
    width = max(len(" ".join(c.words)) for c in commands)
    for cmd in commands:
        lines.append(("  %-*s  %s" % (width, " ".join(cmd.words), cmd.summary)).rstrip())
    return "\n".join(lines) + "\n"


def _group_help(words, commands):
    prefix = tuple(words)
    members = [c for c in commands if c.words[: len(prefix)] == prefix and len(c.words) > len(prefix)]
    nxt = len(prefix)
    lines = ["usage: tallybook %s WORD [ARGUMENTS and --options]" % " ".join(prefix), "", "words:"]
    seen = []
    for cmd in members:
        word = cmd.words[nxt]
        if word not in seen:
            seen.append(word)
    width = max(len(w) for w in seen)
    for word in seen:
        sub = [c for c in members if c.words[nxt] == word]
        summary = sub[0].summary if len(sub[0].words) == nxt + 1 else "%d commands" % len(sub)
        lines.append(("  %-*s  %s" % (width, word, summary)).rstrip())
    return "\n".join(lines) + "\n"


def _command_help(cmd):
    lines = ["usage: tallybook " + cmd.usage, "", cmd.summary]
    return "\n".join(lines) + "\n"


