        if arg in HELP_FLAGS:
            raise _Finished(_root_help(commands))
        if name == "--version":
            if eq:
                raise UsageError("option --version takes no value")
            raise _Finished("tallybook %s\n" % __version__)
        if name not in ("--db", "--today"):
            raise UsageError("unknown option: %s" % arg)
        if name in seen:
            raise UsageError("option %s given more than once" % name)
        seen.add(name)
        if eq:
            i += 1
        else:
            if i + 1 >= len(argv):
                raise UsageError("option %s needs a value" % name)
            value = argv[i + 1]
