        if tuple(words) in by_words:
            return by_words[tuple(words)], words, i
        nxt = argv[i] if i < len(argv) else None
        if nxt in HELP_FLAGS and words:
            return None, words, i
        n = len(words)
        choices = []
        for cmd in commands:
            if cmd.words[:n] == tuple(words) and len(cmd.words) > n and cmd.words[n] not in choices:
                choices.append(cmd.words[n])
        if nxt is None or nxt.startswith("-"):
            if not words:
                raise UsageError("no command given")
            raise UsageError("%s needs a word (%s)" % (" ".join(words), ", ".join(sorted(choices))))
        if nxt not in choices:
            if not words:
                raise UsageError("unknown command: %s" % nxt)
            raise UsageError("unknown word for %s: %s (use %s)" % (" ".join(words), nxt, ", ".join(sorted(choices))))
