def _arity(positionals):
    minimum = 0
    maximum = 0
    for name in positionals:
        optional = name.startswith("[")
        variadic = name.rstrip("]").endswith("...")
        if not optional:
            minimum += 1
        maximum = None if variadic or maximum is None else maximum + 1
    return minimum, maximum


def _parse_command_args(cmd, rest):
    """Split the command's arguments into plain arguments and options."""
    args = []
    opts = {}
    i = 0
    ended = False
    while i < len(rest):
        arg = rest[i]
        i += 1
        if ended or arg == "-" or not arg.startswith("-"):
            args.append(arg)
            continue
        if arg == "--":
            ended = True
            continue
        if arg in HELP_FLAGS:
            raise _Finished(_command_help(cmd))
        if arg.startswith("--"):
            name, eq, value = arg.partition("=")
        elif arg in cmd.aliases:
            name, eq, value = cmd.aliases[arg], "", None
        else:
            args.append(arg)
            continue
        kind = cmd.options.get(name)
        if kind is None:
            raise UsageError("unknown option: %s" % name)
        if kind == "flag":
            if eq:
                raise UsageError("option %s takes no value" % name)
            value = True
        elif not eq:
