            opts.setdefault(name, []).append(value)
        elif name in opts:
            raise UsageError("option %s given more than once" % name)
        else:
            opts[name] = value
    minimum, maximum = _arity(cmd.positionals)
    if len(args) < minimum:
        raise UsageError("missing argument: %s" % cmd.positionals[len(args)].strip("[]."))
    if maximum is not None and len(args) > maximum:
        raise UsageError("too many arguments: %s" % args[maximum])
    for name in cmd.required:
        if name not in opts:
            raise UsageError("missing required option: %s" % name)
    return args, opts


def _check_encodable(args, opts):
    values = list(args)
    for value in opts.values():
        values.extend(value if isinstance(value, list) else [value])
    for value in values:
        if isinstance(value, str):
            try:
                value.encode("utf-8")
            except UnicodeEncodeError:
                raise TallybookError("argument is not valid UTF-8 text: %r" % value, "validation")


def _execute(argv):
    """Run one command line and return its Context, whose buffers hold the output."""
    commands = all_commands()
    state = {}
    start = _parse_global(argv, state, commands)
    db = state.get("db")
    if db is None:
        db = os.environ.get("TALLYBOOK_DB") or "tallybook.db"
    ctx = Context(db, state.get("today"))
    cmd, words, index = _resolve(argv, start, commands)
    if cmd is None:
        raise _Finished(_group_help(words, commands))
    args, opts = _parse_command_args(cmd, argv[index:])
    _check_encodable(args, opts)
    cmd.handler(ctx, args, opts)
    return ctx


def _write(stream, text):
    """Write UTF-8 text to a stream, bypassing newline translation."""
    if not text:
        return
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout():
    """Point file descriptor 1 at /dev/null so the interpreter's exit-time flush stays quiet."""
    try:
        sys.stdout.flush()
    except Exception:
        pass
    try:
        fd = sys.stdout.fileno()
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, fd)
        os.close(devnull)
    except (AttributeError, OSError, ValueError):
        pass


def main(argv=None):
    """Run one command line and return the exit status."""
    argv = list(sys.argv[1:] if argv is None else argv)
    out_text = ""
    err_text = ""
    status = 0
    try:
        ctx = _execute(argv)
        out_text = ctx.stdout_text()
        err_text = ctx.stderr_text()
        status = ctx.exit_status
    except _Finished as done:
        out_text = done.text
    except UsageError as exc:
        err_text = "tallybook: %s\n%s\n" % (exc, TRY_HELP)
        status = 2
    except TallybookError as exc:
        err_text = "tallybook: %s\n" % exc.message
        status = 1
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except KeyboardInterrupt:
        return 130
    except OverflowError:
        err_text = "tallybook: number too large for the book\n"
        status = 1
    except RecursionError:
        err_text = "tallybook: internal error: input too deeply nested\n"
        status = 1
    except MemoryError:
        err_text = "tallybook: internal error: out of memory\n"
        status = 1
    except Exception as exc:
        err_text = "tallybook: internal error: %s: %s\n" % (type(exc).__name__, exc)
        status = 1
    try:
        _write(sys.stdout, out_text)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except (OSError, ValueError) as exc:
        _silence_stdout()
        err_text = "tallybook: cannot write output: %s\n" % (getattr(exc, "strerror", None) or exc)
        status = 1
    try:
        _write(sys.stderr, err_text)
    except (OSError, ValueError):
        pass
    return status


if __name__ == "__main__":
    sys.exit(main())

